package com.example.starter.config;

import java.time.Clock;
import java.time.ZoneId;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时钟配置：业务时间统一走 Clock，便于测试使用可控时钟。
 */
@Configuration
public class ClockConfig {

    /** 业务时区，与 jackson 时区保持一致。 */
    public static final ZoneId BUSINESS_ZONE = ZoneId.of("Asia/Shanghai");

    @Bean
    public Clock businessClock() {
        return Clock.system(BUSINESS_ZONE);
    }
}

package com.example.starter.domain;

/**
 * 引航计划状态机：申请 -> 编排 -> 确认 -> 执行 -> 核销；申请/编排/确认阶段可取消。
 */
public enum PlanStatus {
    /** 已申请，尚未编排。 */
    APPLIED,
    /** 已编排，已绑定引航员、拖轮组合与潮水窗口。 */
    ARRANGED,
    /** 已确认，引航员与拖轮已同事务锁定。 */
    CONFIRMED,
    /** 执行中。 */
    EXECUTING,
    /** 已核销，资源锁定已释放。 */
    SETTLED,
    /** 已取消。 */
    CANCELLED
}

package com.example.starter.domain;

/**
 * 资源锁定类型。
 */
public enum ResourceType {
    /** 引航员。 */
    PILOT,
    /** 拖轮。 */
    TUG
}

package com.example.starter.domain;

import java.time.Duration;
import java.time.LocalDateTime;

/**
 * 半开区间 [start, end)：端点相接不冲突，内部重叠冲突。
 *
 * @param start 区间开始（含）
 * @param end   区间结束（不含）
 */
public record Interval(LocalDateTime start, LocalDateTime end) {

    public Interval {
        if (start == null || end == null) {
            throw new IllegalArgumentException("区间端点不能为空");
        }
        if (!end.isAfter(start)) {
            throw new IllegalArgumentException("区间结束必须晚于开始");
        }
    }

    /**
     * 半开区间重叠判定：[s1,e1) 与 [s2,e2) 内部重叠才算冲突，端点相接（e1==s2 或 e2==s1）不冲突。
     */
    public boolean overlaps(Interval other) {
        return this.start.isBefore(other.end) && other.start.isBefore(this.end);
    }

    /** 区间时长。 */
    public Duration duration() {
        return Duration.between(start, end);
    }
}

