package com.example.starter;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;

/**
 * 测试用可控时钟：可设定与推进，避免时间相关测试依赖真实时间或长时间休眠。
 */
public class MutableClock extends Clock {

    private Instant instant;
    private final ZoneId zone;

    public MutableClock(LocalDateTime dateTime, ZoneId zone) {
        this.instant = dateTime.atZone(zone).toInstant();
        this.zone = zone;
    }

    public void set(LocalDateTime dateTime) {
        this.instant = dateTime.atZone(zone).toInstant();
    }

    public void plus(Duration duration) {
        this.instant = this.instant.plus(duration);
    }

    public LocalDateTime nowDateTime() {
        return LocalDateTime.ofInstant(instant, zone);
    }

    @Override
    public ZoneId getZone() {
        return zone;
    }

    @Override
    public Clock withZone(ZoneId zone) {
        return new MutableClock(LocalDateTime.ofInstant(instant, zone), zone);
    }

    @Override
    public Instant instant() {
        return instant;
    }
}

package com.example.starter;

import java.time.Clock;
import java.time.LocalDateTime;

import org.springframework.beans.factory.DisposableBean;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;
import org.springframework.jdbc.core.JdbcTemplate;

import com.example.starter.config.ClockConfig;

/**
 * 测试基础设施：可控时钟（@Primary 覆盖系统时钟）与测试库释放。
 */
@TestConfiguration
public class TestInfraConfiguration {

    /** 测试基准时间：2026-10-06 00:00 Asia/Shanghai。 */
    public static final LocalDateTime BASE_TIME = LocalDateTime.of(2026, 10, 6, 0, 0);

    @Bean
    @Primary
    public MutableClock mutableClock() {
        return new MutableClock(BASE_TIME, ClockConfig.BUSINESS_ZONE);
    }

    @Bean
    public ClockHolder clockHolder(MutableClock mutableClock) {
        return new ClockHolder(mutableClock);
    }

    /** 让业务注入的 Clock 与测试持有的 MutableClock 是同一实例。 */
    public record ClockHolder(Clock clock) {
    }

    /**
     * 测试上下文关闭时释放 H2 命名内存库（DB_CLOSE_DELAY=-1 不会自动释放）。
     */
    @Bean
    public DisposableBean testDatabaseShutdown(JdbcTemplate jdbcTemplate) {
        return () -> {
            try {
                jdbcTemplate.execute("SHUTDOWN");
            } catch (Exception ignored) {
                // 连接池可能已关闭，忽略释放失败
            }
        };
    }
}

